css:
:root {
  /* Neon Grid Theme - retro wireframe glow */
  --bg-primary: #050510;
  --bg-alt: #0a0a1a;
  --bg-hover: #101028;
  --text-primary: #a6fffd;
  --text-secondary: #7cf4ff;
  --border: #4bf2c4;
  --accent: #ff4fd8;
  --accent-hover: #ff8bed;
  --grid: rgba(75, 242, 196, 0.35);
}

[data-theme="light"] {
  --bg-primary: #eef8ff;
  --bg-alt: #dff1ff;
  --bg-hover: #c8e6ff;
  --text-primary: #082336;
  --text-secondary: #245f73;
  --border: #1ad1a5;
  --accent: #ff4fd8;
  --accent-hover: #ff8bed;
  --grid: rgba(26, 209, 165, 0.25);
}

body {
  background: radial-gradient(circle at 20% 20%, rgba(255, 79, 216, 0.18), transparent 25%),
              radial-gradient(circle at 80% 60%, rgba(75, 242, 196, 0.18), transparent 25%),
              var(--bg-primary);
  color: var(--text-primary);
}

.card {
  background: rgba(10, 10, 26, 0.8);
  border: 1px solid var(--border);
  box-shadow: 0 12px 36px rgba(255, 79, 216, 0.16), 0 0 0 1px rgba(75, 242, 196, 0.15);
  position: relative;
  overflow: hidden;
}

.card::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image: linear-gradient(var(--grid), var(--grid)), linear-gradient(90deg, var(--grid), var(--grid));
  background-size: 28px 1px, 1px 28px;
  opacity: 0.45;
  pointer-events: none;
}

.card-title {
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 1.2px;
}
